+http.Response _chatListPage({
+  required int page,
+  required int totalPages,
+  required List<int> chatIds,
+}) {
+  return http.Response(
+    jsonEncode({
+      'chats': chatIds
+          .map((id) => {
+                'id': 'chat_$id',
+                'title': 'Chat $id',
+                'created_at': '2026-06-01T00:00:00Z',
+                'updated_at': '2026-06-01T00:00:00Z',
+              })
+          .toList(),
+      'pagination': {
+        'page': page,
+        'per_page': 20,
+        'total_count': 5,
+        'total_pages': totalPages,
+      },
+    }),
+    200,
+  );
+}
